        return true;
      }
      // A transient upstream failure (429/5xx/network) is NOT a key verdict —
      // propagate so the caller can distinguish "key is bad" from "provider is
      // down" and avoid falsely telling a tenant their valid key is invalid.
      throw err;
    }
  }

  private toAnthropicContent(
    blocks: LlmContentBlock[],
  ): Anthropic.MessageParam['content'] {
    return blocks.map((block) => {
      switch (block.type) {
        case 'text':
          return { type: 'text', text: block.text };
        case 'tool_use':
          return {
            type: 'tool_use',
            id: block.id,
            name: block.name,
            input: block.input,
          };
        case 'tool_result':
          return {
            type: 'tool_result',
            tool_use_id: block.toolUseId,
            content: block.content,
            is_error: block.isError,
          };
      }
    });
  }

  private mapStopReason(reason: Anthropic.Message['stop_reason']): LlmStopReason {
    switch (reason) {
      case 'end_turn':
      case 'stop_sequence':
        return 'end_turn';
      case 'tool_use':
        return 'tool_use';
      case 'max_tokens':
        return 'max_tokens';
      default:
        return 'other';
    }
  }
}
