 *
 * Every handler pins transaction-local PostgreSQL search_path to the tenant
 * schema before executing queries, ensuring tenant-isolated data access.
 */
@Controller()
export class MessagingNatsHandler {
  private readonly logger = new Logger(MessagingNatsHandler.name);

  constructor(
    @InjectRepository(ChannelMember)
    private readonly memberRepo: Repository<ChannelMember>,
    @InjectRepository(Message)
    private readonly messageRepo: Repository<Message>,
    @InjectDataSource()
    private readonly dataSource: DataSource,
    private readonly partitionManager: PartitionManagerService,
    // LegalHoldService injected for legal hold check in handleUserDeleted.
    // BEFORE: handleUserDeleted anonymized all messages with no hold check —
    // messages in litigation-held channels had their content wiped, destroying evidence.
    private readonly legalHoldService: LegalHoldService,
    // MediaService signs attachment download URLs when hydrating a message for
    // the gateway WS bridge (getMessageForBroadcast).
    private readonly mediaService: MediaService,
    @Inject(REDIS_CLIENT)
    private readonly redis: Redis,
    // MSG-CRITICAL-058: the UserDeleted cascade must delete the MinIO attachment
    // binaries (the user's PII media) for messages it erases, not just the DB rows.
    private readonly attachmentObjectPurge: AttachmentObjectPurgeService,
  ) {}

  /**
   * SEC-M17: Pin the PostgreSQL search_path to the tenant schema for a transaction.
   *
   * Must be called before any tenant-scoped DB operation in NATS handlers,
   * because there is no HTTP middleware to set the schema automatically.
   * Validates tenant ID against strict UUID regex before interpolation to
   * prevent SQL injection via crafted NATS messages from compromised containers.
   *
   * @throws Error if tenantId does not match UUID v4 format
   */
  private async setTenantSchema(queryRunner: QueryRunner, tenantId: string): Promise<void> {
    if (!TENANT_ID_REGEX.test(tenantId)) {
      throw new Error(`SEC-M17: Invalid tenant ID format rejected: ${tenantId.substring(0, 50)}`);
    }
    const schemaName = getTenantSchemaName(tenantId);
    await queryRunner.query(`SELECT pg_catalog.set_config('search_path', $1, true)`, [
      `"${schemaName}", "messaging", public`,
    ]);
  }

  private async withTenantQueryRunner<T>(
    tenantId: string,
    work: (queryRunner: QueryRunner) => Promise<T>,
  ): Promise<T> {
    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();
    await queryRunner.startTransaction();

    try {
      await this.setTenantSchema(queryRunner, tenantId);
      // MSGFIX-FAZ1 (live-diagnosis root cause): search_path ALONE is not
      // enough — the tenant/messaging schema tables sit under FORCE RLS
      // with tenant_isolation_policy: a row is visible only when
      // app.bypass_rls='on' OR "tenantId" = app.current_tenant. This path
      // (unlike the HTTP TenantGuard) never set the GUC, so every NATS
      // request-reply handler (verifyMembership, getChannelMembers,
      // getMessageForBroadcast, resolveNotificationRef) silently read 0
      // rows — WS joins were denied with "not a member" and hydration
      // returned null (evidence: DEPLOY-FAZ1.md §3). bindTenantRlsContext
      // sets the GUC transaction-locally AND reads it back (also forcing a
      // stale bypass 'off') — the canonical backend-common pattern.
      await bindTenantRlsContext(queryRunner, tenantId, 'messaging');
      const result = await work(queryRunner);
      await queryRunner.commitTransaction();
      return result;
    } catch (error) {
      if (queryRunner.isTransactionActive) {
        try {
          await queryRunner.rollbackTransaction();
        } catch (rollbackError: unknown) {
          this.logger.error(
            `Tenant NATS transaction rollback failed: ${errorMessage(rollbackError)}`,
          );
