  ) {
    this.isProduction = this.configService.get<string>('NODE_ENV', 'development') === 'production';
    this.rememberMeRefreshTokenExpiryDays = this.configService.get<number>(
      'REMEMBER_ME_REFRESH_TOKEN_EXPIRY_DAYS',
